import React from 'react';
import { graphql, Link, withPrefix } from 'gatsby';
import Layout from '../components/Layout';
import { useLanguage } from '../context/LanguageContext';
import aviationSvg from '../static/aviation.svg';

const WorksPage = ({ data }) => {
  const { language, t } = useLanguage();
  const markdownNodes = data.allMarkdownRemark.nodes;

  // Filter content based on active language and section
  const worksData = markdownNodes.filter(
    (node) => node.frontmatter.section === 'works' && node.frontmatter.lang === language
  );

  // Exact slug-to-order map to create a perfectly balanced Bento Grid
  const orderMap = {
    'aircraft-on-ground': 1,
    'guideline-dashboards': 2,
    'decentralized-finance-dashboard': 3,
    'minimalist-ecommerce-platform': 4,
    'interactive-space-exhibition': 5
  };

  const sortedWorks = [...worksData].sort((a, b) => {
    const orderA = orderMap[a.frontmatter.slug] || 99;
    const orderB = orderMap[b.frontmatter.slug] || 99;
    return orderA - orderB;
  });

  const getCardImage = (slug) => {
    switch (slug) {
      case 'aircraft-on-ground':
        return aviationSvg;
      case 'guideline-dashboards':
        return withPrefix('/dashboard_mockup.png');
      case 'decentralized-finance-dashboard':
        return 'https://images.unsplash.com/photo-1621761191319-c6fb62004040?q=80&w=600';
      case 'minimalist-ecommerce-platform':
        return 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?q=80&w=600';
      case 'interactive-space-exhibition':
        return 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=600';
      default:
        return 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?q=80&w=600';
    }
  };

  const getCardSizeClass = (slug) => {
    switch (slug) {
      case 'aircraft-on-ground':
        return 'span-8 height-624';
      case 'guideline-dashboards':
        return 'span-10 height-300';
      case 'decentralized-finance-dashboard':
        return 'span-10 height-300';
      case 'minimalist-ecommerce-platform':
        return 'span-10 height-300';
      case 'interactive-space-exhibition':
        return 'span-10 height-300';
      default:
        return 'span-10 height-300';
    }
  };
  const sandboxItems = [
    {
      id: 'sandbox-1',
      titleKey: 'sandbox_item1_title',
      categoryKey: 'sandbox_item1_category',
      excerptKey: 'sandbox_item1_excerpt',
      tags: ['React', 'Framer Motion', 'CSS'],
      image: 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=600',
    },
    {
      id: 'sandbox-2',
      titleKey: 'sandbox_item2_title',
      categoryKey: 'sandbox_item2_category',
      excerptKey: 'sandbox_item2_excerpt',
      tags: ['Three.js', 'WebGL', 'GLSL'],
      image: 'https://images.unsplash.com/photo-1574169208507-84376144848b?q=80&w=600',
    },
    {
      id: 'sandbox-3',
      titleKey: 'sandbox_item3_title',
      categoryKey: 'sandbox_item3_category',
      excerptKey: 'sandbox_item3_excerpt',
      tags: ['GSAP', 'SVG', 'Math'],
      image: 'https://images.unsplash.com/photo-1614850523459-c2f4c699c52e?q=80&w=600',
    },
    {
      id: 'sandbox-4',
      titleKey: 'sandbox_item4_title',
      categoryKey: 'sandbox_item4_category',
      excerptKey: 'sandbox_item4_excerpt',
      tags: ['OpenAI', 'Tailwind', 'JSON'],
      image: 'https://images.unsplash.com/photo-1634017839464-5c339ebe3cb4?q=80&w=600',
    },
  ];

  return (
    <Layout>
      <div className="container works-page">
        <div className="works-header-intro">
          <h1>{t('works_title')}</h1>
          <p>{t('works_subtitle')}</p>
        </div>

        <div className="bento-grid">
          {/* Intro Card */}
          <div className="bento-item title-card span-12 height-300">
            <svg className="bento-bg-blob" viewBox="0 0 728 774" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M209.23 492.909C167.957 582.974 201.473 761.298 378.374 710.8C617.512 642.536 663.284 467.69 596.38 287.408C522.606 88.6144 312.404 41.0368 163.83 149.715C15.2554 258.393 250.502 402.845 209.23 492.909Z" fill="#D1D5DB" fillOpacity="0.5" />
              <path d="M556.492 510.166C674.291 361.65 613.273 178.947 461.36 115.724C423.433 99.9392 394.978 103.524 372.222 117.853C349.422 132.21 332.269 157.394 317.073 184.967C309.478 198.749 302.384 213.103 295.317 226.981C288.254 240.852 281.218 254.246 273.75 266.078C258.832 289.718 242.107 307.266 219.827 309.844C175.896 314.927 123.746 344.512 97.6594 386.764C84.6247 407.876 78.1061 432.135 82.3472 458.08C86.5889 484.028 101.603 511.721 131.742 539.678C213.311 615.34 292.783 641.6 365.179 632.165C437.59 622.728 503.032 577.567 556.492 510.166Z" stroke="black" />
            </svg>
            <h2 className="hero-title" style={{ fontSize: '2.2rem' }}>
              CREATIVE PORTFOLIO<br />
              <span className="action">WORKS</span>
            </h2>
          </div>

          {/* Dynamically Rendered Work Cards */}
          {sortedWorks.map((work) => {
            const { title, slug, category, tags } = work.frontmatter;
            const excerpt = work.excerpt || '';
            const bgImage = getCardImage(slug);
            const sizeClass = getCardSizeClass(slug);

            return (
              <div key={work.id} className={`bento-item img-card ${sizeClass}`}>
                <Link to={`/project/${slug}`} className="bento-card-link">
                  <div>
                    <div className="bento-card-category">{category}</div>
                    <h3 className="bento-card-title">{title}</h3>
                    <p className="bento-card-excerpt">{excerpt}</p>
                  </div>
                  <div className="bento-card-tags">
                    {tags && tags.slice(0, 3).map((tag, idx) => (
                      <span key={idx} className="bento-card-tag">{tag}</span>
                    ))}
                  </div>
                </Link>
                <div
                  className="bento-card-image-bg"
                  style={{ backgroundImage: `url(${bgImage})` }}
                />
              </div>
            );
          })}
        </div>

        {/* Sandbox Section */}
        <section className="sandbox-section" style={{ marginTop: '80px', paddingTop: '60px', borderTop: '1px solid var(--border-color)' }}>
          <div className="works-header-intro" style={{ marginBottom: '40px' }}>
            <h2 style={{ fontSize: '3rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '-0.03em', marginBottom: '12px', color: 'var(--text-primary)' }}>
              {t('nav_sandbox')}
            </h2>
            <p style={{ color: 'var(--text-secondary)', fontSize: '1.2rem', maxWidth: '600px', lineHeight: 1.6 }}>
              {t('sandbox_subtitle')}
            </p>
          </div>

          <div className="bento-grid">
            {sandboxItems.map((item) => (
              <div key={item.id} className="bento-item img-card span-5 height-300">
                <div className="bento-card-link" style={{ cursor: 'default' }}>
                  <div>
                    <div className="bento-card-category">{t(item.categoryKey)}</div>
                    <h3 className="bento-card-title">{t(item.titleKey)}</h3>
                    <p className="bento-card-excerpt">{t(item.excerptKey)}</p>
                  </div>
                  <div className="bento-card-tags">
                    {item.tags.map((tag, idx) => (
                      <span key={idx} className="bento-card-tag">{tag}</span>
                    ))}
                  </div>
                </div>
                <div
                  className="bento-card-image-bg"
                  style={{ backgroundImage: `url(${item.image})` }}
                />
              </div>
            ))}
          </div>
        </section>
      </div>
    </Layout>
  );
};

export const query = graphql`
  query {
    allMarkdownRemark {
      nodes {
        id
        excerpt(pruneLength: 120)
        frontmatter {
          title
          slug
          lang
          section
          category
          tags
          order
        }
      }
    }
  }
`;

export default WorksPage;
